-- Public prerequisites for the 18 v14 experiment units. Generated from oslab_db.
-- No user, task, progress, attempt, review or AI data. Teaching ownership is system 0.
-- Inserts missing public rows only. Existing rows are preserved, except untouched v6 empty unit templates.
-- Apply before oslab_upgrade_v14_experiment_judge.sql in fresh installs. Do not use mysql --force.
SET NAMES utf8mb4;
START TRANSACTION;
CREATE TEMPORARY TABLE _v14_prerequisite_guard(ok TINYINT NOT NULL CHECK (ok=1));
CREATE TEMPORARY TABLE _v14_unit_templates AS SELECT unitCode FROM learning_unit WHERE revision=1 AND reviewStatus='DRAFT' AND publishedJson IS NULL AND estimatedMinutes=0 AND contributor='L' AND userId=0 AND isDelete=0 AND ((id=610000000000000042 AND unitCode=CONVERT(X'756e69742e6f766572766965772e72756e74696d652d6d6f646573' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND courseCode=CONVERT(X'636f757273652e6f7065726174696e672d73797374656d73' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND sectionCode=CONVERT(X'7365632e6f766572766965772e72756e74696d65' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND title=CONVERT(X'e794a8e688b7e68081e4b88ee58685e6a0b8e68081' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND sortOrder=4 AND draftJson <=> CAST(CONVERT(X'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS JSON)) OR (id=610000000000000043 AND unitCode=CONVERT(X'756e69742e6f766572766965772e696e7465727275707473' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND courseCode=CONVERT(X'636f757273652e6f7065726174696e672d73797374656d73' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND sectionCode=CONVERT(X'7365632e6f766572766965772e72756e74696d65' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND title=CONVERT(X'e4b8ade696ade4b88ee5bc82e5b8b8' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND sortOrder=5 AND draftJson <=> CAST(CONVERT(X'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS JSON)) OR (id=610000000000000044 AND unitCode=CONVERT(X'756e69742e6f766572766965772e73797374656d2d63616c6c73' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND courseCode=CONVERT(X'636f757273652e6f7065726174696e672d73797374656d73' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND sectionCode=CONVERT(X'7365632e6f766572766965772e72756e74696d65' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND title=CONVERT(X'e5ba94e794a8e5a682e4bd95e8afb7e6b182e6938de4bd9ce7b3bbe7bb9fe69c8de58aa1' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND sortOrder=6 AND draftJson <=> CAST(CONVERT(X'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS JSON)) OR (id=610000000000000046 AND unitCode=CONVERT(X'756e69742e6f766572766965772e626f6f74' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND courseCode=CONVERT(X'636f757273652e6f7065726174696e672d73797374656d73' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND sectionCode=CONVERT(X'7365632e6f766572766965772e626f6f74' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND title=CONVERT(X'e6938de4bd9ce7b3bbe7bb9fe5bc95e5afbc' USING utf8mb4) COLLATE utf8mb4_unicode_ci AND sortOrder=8 AND draftJson <=> CAST(CONVERT(X'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS JSON)));
SET @v14_template=(SELECT COUNT(*) FROM _v14_unit_templates WHERE unitCode=CONVERT(X'756e69742e6f766572766965772e72756e74696d652d6d6f646573' USING utf8mb4) COLLATE utf8mb4_unicode_ci);
